import type { Metadata } from "next";

// The landing page is the only indexable page (#277), so it alone names the
// canonical URL. Its client page cannot export metadata, hence this layout. It
// must not set openGraph: a deeper segment's openGraph replaces the root one,
// including the image generated by app/opengraph-image.tsx.
export const metadata: Metadata = {
  alternates: { canonical: "/" },
};

export default function LandingLayout({ children }: Readonly<{ children: React.ReactNode }>) {
  return children;
}
